#!/usr/bin/env node
// Generates protocol types from packages/shared/protocol.schema.json (the single source of truth).
//   node scripts/gen-protocol.mjs          write generated files
//   node scripts/gen-protocol.mjs --check  exit 1 if generated files are stale (used by CI)
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schema = join(root, "packages/shared/protocol.schema.json");
const quicktype = join(root, "node_modules/.bin/quicktype");
const header = "// GENERATED by scripts/gen-protocol.mjs from packages/shared/protocol.schema.json. Do not edit.\n";

const targets = [
  {
    out: "packages/shared/src/protocol.gen.ts",
    args: ["--lang", "typescript", "--just-types", "--prefer-const-values", "--acronym-style", "original", "--top-level", "ProtocolRoot"],
  },
  {
    out: "native/macos/Sources/AgentCore/Protocol.gen.swift",
    args: ["--lang", "swift", "--sendable", "--protocol", "equatable",
           "--acronym-style", "original", "--access-level", "public", "--top-level", "ProtocolRoot"],
  },
];

// The protocol version lives in the schema (x-protocolVersion) so both languages read one number.
const protocolVersion = JSON.parse(readFileSync(schema, "utf8"))["x-protocolVersion"];
if (!Number.isInteger(protocolVersion) || protocolVersion < 1) throw new Error("x-protocolVersion must be a positive integer");
const trailers = {
  "packages/shared/src/protocol.gen.ts":
    `\n/** Agent and daemon must agree on this, or auto-recording is blocked. */\nexport const PROTOCOL_VERSION = ${protocolVersion};\n`,
  "native/macos/Sources/AgentCore/Protocol.gen.swift":
    `\n/// Agent and daemon must agree on this, or auto-recording is blocked.\npublic let protocolVersion = ${protocolVersion}\n`,
};

const check = process.argv.includes("--check");
const scratch = mkdtempSync(join(tmpdir(), "gen-protocol-"));
let stale = 0;
try {
  for (const { out, args } of targets) {
    const tmp = join(scratch, out.split("/").pop());
    execFileSync(quicktype, ["--src-lang", "schema", ...args, "-o", tmp, schema], { stdio: "inherit" });
    const generated = header + readFileSync(tmp, "utf8") + trailers[out];
    const target = join(root, out);
    if (check) {
      const current = existsSync(target) ? readFileSync(target, "utf8") : "";
      if (current !== generated) { console.error(`STALE ${out} (run: npm run gen:protocol)`); stale++; }
      else console.log(`OK    ${out}`);
    } else {
      writeFileSync(target, generated);
      console.log(`wrote ${out}`);
    }
  }
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
process.exit(stale ? 1 : 0);
